/**
 * 페이지 시각 효과 튜닝
 * ─────────────────────────────────────────────────────────
 * 이 파일만 수정하면 청첩장의 배경 효과가 즉시 바뀝니다.
 * 변경 후 저장 → 브라우저 새로고침으로 확인.
 */
export const effectsConfig = {
  // ─────────────────────────────────────────────────────────
  // 떠다니는 구름 효과 (배경 길상문 구름)
  // ─────────────────────────────────────────────────────────
  clouds: {
    // 켜기/끄기
    enabled: true,

    // 📌 구름 개수 결정 방식
    //   - count 가 숫자면 그 개수로 고정 (페이지 길이와 무관)
    //   - count 가 null 이면 density × 페이지수 만큼 자동
    //     (페이지가 길수록 구름이 더 많이 생겨 빈 공간 없이 채워줌)
    count: null,
    density: 4,             // 한 화면(=100vh) 당 구름 몇 개 (1~6 권장)

    // 📏 세로 간격
    // verticalJitter: 균등 분포에서 ±% 만큼 흔들기 (0 = 완벽한 등간격, 50 = 자유분방)
    verticalJitter: 35,

    // 📐 구름 크기 (px) — 이 범위에서 랜덤
    sizeMin: 80,
    sizeMax: 170,

    // 🕐 한 번 가로지르는 데 걸리는 시간 (초)
    //   값이 작을수록 빠릅니다. 너무 빠르면 산만하므로 60~120 권장
    speedMin: 60,
    speedMax: 120,

    // 🌊 위아래 흔들림 (px) — 둥둥 떠다니는 듯한 출렁임
    //   0 이면 일직선, 12~20 정도면 부드럽게 둥실둥실
    swayAmount: 8,

    // 🌫️ 투명도 — 너무 진하면 본문 가독성이 떨어집니다 (0.04~0.15 권장)
    opacityMin: 0.05,
    opacityMax: 0.12,

    // ➡️ 좌·우 방향 비율 (1 = 모두 오른쪽, 0 = 모두 왼쪽, 0.5 = 반반)
    rightwardRatio: 0.5,

    // ☁️ 사용할 구름 종류 (invitation.js 의 ornaments 키)
    variants: ['cloud1', 'cloud2', 'cloud3'],
  },
}
